      "INSERT INTO \"public\".\"_electric_trigger_settings\" (\"namespace\", \"tablename\", \"flag\")\n  VALUES ('public', 'accounts', 1)\n  ON CONFLICT DO NOTHING;",
      "DROP TRIGGER IF EXISTS update_ensure_public_accounts_primarykey ON \"public\".\"accounts\";",
      "CREATE OR REPLACE FUNCTION update_ensure_public_accounts_primarykey_function()\nRETURNS TRIGGER AS $$\nBEGIN\n  IF OLD.\"provider\" IS DISTINCT FROM NEW.\"provider\" THEN\n    RAISE EXCEPTION 'Cannot change the value of column provider as it belongs to the primary key';\n  END IF;\n  IF OLD.\"provider_account_id\" IS DISTINCT FROM NEW.\"provider_account_id\" THEN\n    RAISE EXCEPTION 'Cannot change the value of column provider_account_id as it belongs to the primary key';\n  END IF;\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql;",
      "CREATE TRIGGER update_ensure_public_accounts_primarykey\n  BEFORE UPDATE ON \"public\".\"accounts\"\n    FOR EACH ROW\n      EXECUTE FUNCTION update_ensure_public_accounts_primarykey_function();",
      "DROP TRIGGER IF EXISTS insert_public_accounts_into_oplog ON \"public\".\"accounts\";",
      "    CREATE OR REPLACE FUNCTION insert_public_accounts_into_oplog_function()\n    RETURNS TRIGGER AS $$\n    BEGIN\n      DECLARE\n        flag_value INTEGER;\n      BEGIN\n        -- Get the flag value from _electric_trigger_settings\n        SELECT flag INTO flag_value FROM \"public\"._electric_trigger_settings WHERE namespace = 'public' AND tablename = 'accounts';\n\n        IF flag_value = 1 THEN\n          -- Insert into _electric_oplog\n          INSERT INTO \"public\"._electric_oplog (namespace, tablename, optype, \"primaryKey\", \"newRow\", \"oldRow\", timestamp)\n          VALUES (\n            'public',\n            'accounts',\n            'INSERT',\n            json_strip_nulls(json_build_object('provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\")),\n            jsonb_build_object('access_token', new.\"access_token\", 'expires_at', new.\"expires_at\", 'id_token', new.\"id_token\", 'provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\", 'refresh_token', new.\"refresh_token\", 'scope', new.\"scope\", 'session_state', new.\"session_state\", 'token_type', new.\"token_type\", 'type', new.\"type\", 'userId', new.\"userId\"),\n            NULL,\n            NULL\n          );\n        END IF;\n\n        RETURN NEW;\n      END;\n    END;\n    $$ LANGUAGE plpgsql;",
      "CREATE TRIGGER insert_public_accounts_into_oplog\n  AFTER INSERT ON \"public\".\"accounts\"\n    FOR EACH ROW\n      EXECUTE FUNCTION insert_public_accounts_into_oplog_function();",
      "DROP TRIGGER IF EXISTS update_public_accounts_into_oplog ON \"public\".\"accounts\";",
      "    CREATE OR REPLACE FUNCTION update_public_accounts_into_oplog_function()\n    RETURNS TRIGGER AS $$\n    BEGIN\n      DECLARE\n        flag_value INTEGER;\n      BEGIN\n        -- Get the flag value from _electric_trigger_settings\n        SELECT flag INTO flag_value FROM \"public\"._electric_trigger_settings WHERE namespace = 'public' AND tablename = 'accounts';\n\n        IF flag_value = 1 THEN\n          -- Insert into _electric_oplog\n          INSERT INTO \"public\"._electric_oplog (namespace, tablename, optype, \"primaryKey\", \"newRow\", \"oldRow\", timestamp)\n          VALUES (\n            'public',\n            'accounts',\n            'UPDATE',\n            json_strip_nulls(json_build_object('provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\")),\n            jsonb_build_object('access_token', new.\"access_token\", 'expires_at', new.\"expires_at\", 'id_token', new.\"id_token\", 'provider', new.\"provider\", 'provider_account_id', new.\"provider_account_id\", 'refresh_token', new.\"refresh_token\", 'scope', new.\"scope\", 'session_state', new.\"session_state\", 'token_type', new.\"token_type\", 'type', new.\"type\", 'userId', new.\"userId\"),\n            jsonb_build_object('access_token', old.\"access_token\", 'expires_at', old.\"expires_at\", 'id_token', old.\"id_token\", 'provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\", 'refresh_token', old.\"refresh_token\", 'scope', old.\"scope\", 'session_state', old.\"session_state\", 'token_type', old.\"token_type\", 'type', old.\"type\", 'userId', old.\"userId\"),\n            NULL\n          );\n        END IF;\n\n        RETURN NEW;\n      END;\n    END;\n    $$ LANGUAGE plpgsql;",
      "CREATE TRIGGER update_public_accounts_into_oplog\n  AFTER UPDATE ON \"public\".\"accounts\"\n    FOR EACH ROW\n      EXECUTE FUNCTION update_public_accounts_into_oplog_function();",
      "DROP TRIGGER IF EXISTS delete_public_accounts_into_oplog ON \"public\".\"accounts\";",
      "    CREATE OR REPLACE FUNCTION delete_public_accounts_into_oplog_function()\n    RETURNS TRIGGER AS $$\n    BEGIN\n      DECLARE\n        flag_value INTEGER;\n      BEGIN\n        -- Get the flag value from _electric_trigger_settings\n        SELECT flag INTO flag_value FROM \"public\"._electric_trigger_settings WHERE namespace = 'public' AND tablename = 'accounts';\n\n        IF flag_value = 1 THEN\n          -- Insert into _electric_oplog\n          INSERT INTO \"public\"._electric_oplog (namespace, tablename, optype, \"primaryKey\", \"newRow\", \"oldRow\", timestamp)\n          VALUES (\n            'public',\n            'accounts',\n            'DELETE',\n            json_strip_nulls(json_build_object('provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\")),\n            NULL,\n            jsonb_build_object('access_token', old.\"access_token\", 'expires_at', old.\"expires_at\", 'id_token', old.\"id_token\", 'provider', old.\"provider\", 'provider_account_id', old.\"provider_account_id\", 'refresh_token', old.\"refresh_token\", 'scope', old.\"scope\", 'session_state', old.\"session_state\", 'token_type', old.\"token_type\", 'type', old.\"type\", 'userId', old.\"userId\"),\n            NULL\n          );\n        END IF;\n\n        RETURN NEW;\n      END;\n    END;\n    $$ LANGUAGE plpgsql;",
      "CREATE TRIGGER delete_public_accounts_into_oplog\n  AFTER DELETE ON \"public\".\"accounts\"\n    FOR EACH ROW\n      EXECUTE FUNCTION delete_public_accounts_into_oplog_function();",
      "DROP TRIGGER IF EXISTS compensation_insert_public_accounts_userId_into_oplog ON \"public\".\"accounts\";",
      "    CREATE OR REPLACE FUNCTION compensation_insert_public_accounts_userId_into_oplog_function()\n    RETURNS TRIGGER AS $$\n    BEGIN\n      DECLARE\n        flag_value INTEGER;\n        meta_value INTEGER;\n      BEGIN\n        SELECT flag INTO flag_value FROM \"public\"._electric_trigger_settings WHERE namespace = 'public' AND tablename = 'accounts';\n\n        SELECT value INTO meta_value FROM \"public\"._electric_meta WHERE key = 'compensations';\n\n        IF flag_value = 1 AND meta_value = 1 THEN\n          INSERT INTO \"public\"._electric_oplog (namespace, tablename, optype, \"primaryKey\", \"newRow\", \"oldRow\", timestamp)\n          SELECT\n            'public',\n            'users',\n            'COMPENSATION',\n            json_strip_nulls(json_strip_nulls(json_build_object('id', \"id\"))),\n            jsonb_build_object('id', \"id\"),\n            NULL,\n            NULL\n          FROM \"public\".\"users\"\n          WHERE \"id\" = NEW.\"userId\";\n        END IF;\n\n        RETURN NEW;\n      END;\n    END;\n    $$ LANGUAGE plpgsql;",
      "CREATE TRIGGER compensation_insert_public_accounts_userId_into_oplog\n  AFTER INSERT ON \"public\".\"accounts\"\n    FOR EACH ROW\n      EXECUTE FUNCTION compensation_insert_public_accounts_userId_into_oplog_function();",
